"""AES-GCM via OpenSSL AES-NI, parallelized across cores.

CTR and GHASH are independent per block-aligned chunk, so each worker encrypts
its slice and authenticates it. The chunk tags are folded with a GHASH-field
multiply (H raised to the later chunk lengths) so the tag matches AES-GCM.
"""
import aesgcm_fast


class Solver:
    def solve(self, problem, **kwargs):
        aad = problem["associated_data"] or b""
        return aesgcm_fast.encrypt(problem["key"], problem["nonce"], problem["plaintext"], aad)

