#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <openssl/aes.h>

extern int aesni_set_encrypt_key(const unsigned char *userKey, int bits, AES_KEY *key);
extern void aesni_encrypt(const unsigned char *in, unsigned char *out, const AES_KEY *key);
extern void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out,
                                       size_t blocks, const AES_KEY *key, const unsigned char ivec[16]);
extern void gcm_init_avx(void *Htable, const unsigned char H[16]);
extern void gcm_ghash_avx(unsigned char Xi[16], const void *Htable, const unsigned char *in, size_t len);

#define NTHREADS 6
static unsigned char *PT, *CT;
static AES_KEY key;
static size_t nblocks;
static unsigned char nonce[12];

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

static void *worker(void *arg){
    long id = (long)arg;
    size_t chunk = nblocks / NTHREADS;
    size_t start = id * chunk;
    size_t nb = (id == NTHREADS-1) ? (nblocks - start) : chunk;
    unsigned char ivec[16];
    memcpy(ivec, nonce, 12);
    uint32_t ctr = 2 + (uint32_t)start;
    ivec[12] = ctr>>24; ivec[13]=ctr>>16; ivec[14]=ctr>>8; ivec[15]=ctr;
    aesni_ctr32_encrypt_blocks(PT + start*16, CT + start*16, nb, &key, ivec);
    return NULL;
}

int main(){
    size_t n = 60000*1024;
    nblocks = n/16;
    PT = aligned_alloc(64, n);
    CT = aligned_alloc(64, n);
    memset(PT, 0x5a, n);
    unsigned char keyb[16]; memset(keyb, 1, 16);
    memset(nonce, 2, 12);
    aesni_set_encrypt_key(keyb, 128, &key);

    /* warmup */
    pthread_t th[NTHREADS];
    for(int i=0;i<NTHREADS;i++) pthread_create(&th[i], NULL, worker, (void*)(long)i);
    for(int i=0;i<NTHREADS;i++) pthread_join(th[i], NULL);

    int reps=5;
    double t0=now();
    for(int r=0;r<reps;r++){
        for(int i=0;i<NTHREADS;i++) pthread_create(&th[i], NULL, worker, (void*)(long)i);
        for(int i=0;i<NTHREADS;i++) pthread_join(th[i], NULL);
    }
    double t1=now();
    printf("parallel CTR %d threads: %.4f s  %.0f MB/s\n", NTHREADS, (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

    /* single thread ctr */
    t0=now();
    for(int r=0;r<reps;r++){
        unsigned char ivec[16]; memcpy(ivec, nonce, 12);
        ivec[15]=2;
        aesni_ctr32_encrypt_blocks(PT, CT, nblocks, &key, ivec);
    }
    t1=now();
    printf("single CTR: %.4f s  %.0f MB/s\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

    /* ghash */
    unsigned char H[16], zero[16]={0};
    aesni_encrypt(zero, H, &key);
    /* bswap */
    unsigned char Hb[16];
    for(int i=0;i<8;i++){ Hb[i]=H[7-i]; Hb[8+i]=H[15-i]; }
    unsigned char Htable[512];
    gcm_init_avx(Htable, Hb);
    unsigned char Xi[16]={0};
    t0=now();
    for(int r=0;r<reps;r++){
        memset(Xi,0,16);
        gcm_ghash_avx(Xi, Htable, CT, n);
    }
    t1=now();
    printf("ghash: %.4f s  %.0f MB/s\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));
    return 0;
}
