#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <stdint.h>
#include <string.h>
#include <openssl/aes.h>

extern int aesni_set_encrypt_key(const unsigned char *userKey, int bits, AES_KEY *key);
extern void aesni_encrypt(const unsigned char *in, unsigned char *out, const AES_KEY *key);
extern size_t aesni_gcm_encrypt(const unsigned char *in, unsigned char *out, size_t len,
                                const void *key, unsigned char ivec[16], uint64_t *Xi);

static PyObject *fast_encrypt(PyObject *self, PyObject *args) {
    Py_buffer key_buf, nonce_buf, pt_buf, aad_buf;
    memset(&aad_buf, 0, sizeof(aad_buf));
    if (!PyArg_ParseTuple(args, "y*y*y*|y*", &key_buf, &nonce_buf, &pt_buf, &aad_buf))
        return NULL;

    if (key_buf.len != 16 && key_buf.len != 24 && key_buf.len != 32) {
        PyErr_SetString(PyExc_ValueError, "bad key size");
        goto fail;
    }
    if (pt_buf.len < 0) {
        PyErr_SetString(PyExc_ValueError, "bad pt");
        goto fail;
    }

    AES_KEY key;
    if (aesni_set_encrypt_key((const unsigned char *)key_buf.buf, (int)key_buf.len * 8, &key) != 0) {
        PyErr_SetString(PyExc_RuntimeError, "set_key failed");
        goto fail;
    }

    PyObject *ct_obj = PyBytes_FromStringAndSize(NULL, pt_buf.len);
    PyObject *tag_obj = PyBytes_FromStringAndSize(NULL, 16);
    if (!ct_obj || !tag_obj) {
        Py_XDECREF(ct_obj);
        Py_XDECREF(tag_obj);
        goto fail;
    }
    unsigned char *ct = (unsigned char *)PyBytes_AS_STRING(ct_obj);
    unsigned char *tag = (unsigned char *)PyBytes_AS_STRING(tag_obj);

    unsigned char ivec[16];
    uint64_t Xi[2] = {0, 0}; /* 16 bytes; function may expect more but writes Xi as 128-bit */

    /* Use a larger Xi area in case the asm touches neighbors via the calling convention.
       We pass a 64-byte aligned buffer. */
    unsigned char xi_area[64];
    memset(xi_area, 0, sizeof(xi_area));

    size_t n = (size_t)pt_buf.len;
    size_t bulk = n & ~(size_t)15; /* multiple of 16? aesni_gcm_encrypt requires len>=0x120 and processes floor? */
    /* From earlier probe: ret = len & ~15? 1048512 for 1MB=1048576, difference 64.
       Actually 1048576-1048512=64. Hmm 0x40. Let's just call and see.
       For correctness test we'll compare. */

    memset(ivec, 0, 16);
    if (nonce_buf.len == 12) {
        memcpy(ivec, nonce_buf.buf, 12);
        ivec[15] = 1;
    } else {
        /* unsupported for now */
        PyErr_SetString(PyExc_ValueError, "only 12-byte nonce in this probe");
        Py_DECREF(ct_obj);
        Py_DECREF(tag_obj);
        goto fail;
    }

    size_t done = 0;
    if (bulk >= 0x120) {
        done = aesni_gcm_encrypt((const unsigned char *)pt_buf.buf, ct, bulk, &key, ivec, (uint64_t *)xi_area);
    }
    /* record what happened */
    PyObject *info = Py_BuildValue("nnny#y#", (Py_ssize_t)done, (Py_ssize_t)bulk,
                                   (Py_ssize_t)n, ivec, 16, xi_area, 32);
    Py_DECREF(ct_obj);
    Py_DECREF(tag_obj);
    PyBuffer_Release(&key_buf);
    PyBuffer_Release(&nonce_buf);
    PyBuffer_Release(&pt_buf);
    if (aad_buf.buf) PyBuffer_Release(&aad_buf);
    return info;

fail:
    PyBuffer_Release(&key_buf);
    PyBuffer_Release(&nonce_buf);
    PyBuffer_Release(&pt_buf);
    if (aad_buf.buf) PyBuffer_Release(&aad_buf);
    return NULL;
}

static PyMethodDef methods[] = {
    {"probe", fast_encrypt, METH_VARARGS, NULL},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "aesgcm_fast", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_aesgcm_fast(void) { return PyModule_Create(&moduledef); }
