    unsigned char ivec[16];
    memcpy(ivec, nv, 12);
    ivec[12]=0; ivec[13]=0; ivec[14]=0; ivec[15]=2;
    aesni_ctr32_encrypt_blocks(pt, ct, 4, &aeskey, ivec);

