    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char ect[64+16];
    int outl=0, tot=0;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, keyb, nv);
    EVP_EncryptUpdate(ctx, NULL, &outl, aad, 4);
    EVP_EncryptUpdate(ctx, ect, &outl, pt, 64); tot=outl;
    EVP_EncryptFinal_ex(ctx, ect+tot, &outl);
    unsigned char etag[16];
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, etag);
    printf("ct match %d\n", memcmp(ct, ect, 64)==0);
    printf("tag match %d\n", memcmp(tag, etag, 16)==0);
    printf("our tag "); for(int i=0;i<16;i++) printf("%02x", tag[i]);
    printf("\nevp tag "); for(int i=0;i<16;i++) printf("%02x", etag[i]);
    printf("\n");

