    chunk_blocks = (n/16) / nchunks;
    size_t used = 0;
    for(int c=0;c<nchunks;c++){
        chunk_lens[c] = chunk_blocks;
        used += chunk_blocks*16;
    }
    /* ignore tail for timing */

    pthread_t th[8];
