extern void gcm_ghash_avx(unsigned char Xi[16], const void *Htable, const unsigned char *in, size_t len);

static void bswap16(unsigned char *p){
    for(int i=0;i<8;i++){ unsigned char t=p[i]; p[i]=p[15-i]; p[15-i]=t; }
}
static void bswap_halves(unsigned char *p){
    for(int i=0;i<4;i++){ unsigned char t=p[i]; p[i]=p[7-i]; p[7-i]=t; t=p[8+i]; p[8+i]=p[15-i]; p[15-i]=t; }
