/* Standard non-reflected GHASH multiply (MSB first), Intel whitepaper style
   but with the polynomial reduction for the NON-reflected representation.
   We'll also try reflected. Print both. */

static __m128i clmul_reduce_reflected(__m128i lo, __m128i hi) {
    /* Gueron / Kounavis reflected reduction.
       poly = 0xe1 << 120 placed in high? The widely copied snippet:

       __m128i tmp7, tmp8, tmp9;
       tmp7 = _mm_srli_epi32(lo, 31);
       tmp8 = _mm_srli_epi32(hi, 31);
       lo = _mm_slli_epi32(lo, 1);
       hi = _mm_slli_epi32(hi, 1);
       ... that's the bit-reflect shift approach. Use the pclmul one:

       From Intel CLMUL app note (reflected):
         __m128i POLY = _mm_setr_epi32(0x1, 0, 0, 0xc2000000); // sometimes
    */
    const __m128i POLY = _mm_setr_epi32(0xe1000000, 0, 0, 0);
    __m128i t1 = _mm_clmulepi64_si128(lo, POLY, 0x00);
    __m128i t2 = _mm_xor_si128(lo, _mm_slli_si128(t1, 8));
    __m128i t3 = _mm_clmulepi64_si128(t2, POLY, 0x01); /* ? */
    (void)t3;
    /* The classic 2-step:
       v1 = clmul(lo.low64, poly)
       lo ^= v1 << 64
       v2 = clmul(lo.high64, poly)
       hi ^= v1 >> 64
       hi ^= v2
    */
    __m128i poly = _mm_set_epi64x(0, 0xe1000000ull); /* low qword = 0xe1000000 */
    __m128i v1 = _mm_clmulepi64_si128(lo, poly, 0x00);
    __m128i lo2 = _mm_xor_si128(lo, _mm_slli_si128(v1, 8));
    __m128i v2 = _mm_clmulepi64_si128(lo2, poly, 0x10); /* high qword of lo2 * low of poly? imm 0x10 is a.high * b.low */
    /* wait imm: 0x00 = a0*b0, 0x01 = a1*b0, 0x10 = a0*b1, 0x11 = a1*b1.
       We want high qword of lo2 times poly.low. That's imm 0x01 (a.high * b.low). */
    v2 = _mm_clmulepi64_si128(lo2, poly, 0x01);
    __m128i hi2 = _mm_xor_si128(hi, _mm_srli_si128(v1, 8));
    hi2 = _mm_xor_si128(hi2, v2);
    return hi2;
}

static void mul_reflected(unsigned char out[16], const unsigned char a[16], const unsigned char b[16]) {
    __m128i A = _mm_loadu_si128((const __m128i *)a);
    __m128i B = _mm_loadu_si128((const __m128i *)b);
    __m128i lo = _mm_clmulepi64_si128(A, B, 0x00);
    __m128i hi = _mm_clmulepi64_si128(A, B, 0x11);
    __m128i m1 = _mm_clmulepi64_si128(A, B, 0x01);
    __m128i m2 = _mm_clmulepi64_si128(A, B, 0x10);
    __m128i mid = _mm_xor_si128(m1, m2);
    lo = _mm_xor_si128(lo, _mm_slli_si128(mid, 8));
    hi = _mm_xor_si128(hi, _mm_srli_si128(mid, 8));
    __m128i r = clmul_reduce_reflected(lo, hi);
    _mm_storeu_si128((__m128i *)out, r);
}

int main(){
    unsigned char keyb[16]; for(int i=0;i<16;i++) keyb[i]=i;
    AES_KEY key; aesni_set_encrypt_key(keyb, 128, &key);
    unsigned char H[16], z[16]={0};
