    for(int i=0;i<8;i++){ Hb[i]=H[7-i]; Hb[8+i]=H[15-i]; }
    unsigned char htable[512]; memset(htable,0,sizeof(htable));
    gcm_init_avx(htable, Hb);

    unsigned char block[16]; for(int i=0;i<16;i++) block[i]=0x10+i;
    unsigned char expect[16]; memset(expect,0,16);
    gcm_ghash_avx(expect, htable, block, 16);
    phex("expect", expect);
    phex("H     ", H);
    phex("Hb    ", Hb);
    phex("block ", block);

    __m128i B = _mm_loadu_si128((const __m128i *)block);
    __m128i Hv = _mm_loadu_si128((const __m128i *)H);
    __m128i Hbv = _mm_loadu_si128((const __m128i *)Hb);
    __m128i Bs = B, Hs = Hv; bswap16_m(&Bs); bswap16_m(&Hs);

