    cands[6] = gf_mul(Bs, Hs); bswap16_m(&cands[6]);
    cands[7] = gf_mul(B, Hv); bswap16_m(&cands[7]);

    const char *names[]={"mul(B,Hb)","mul(B,H)","mul(bswapB,bswapH)","mul(bswapB,Hb)",
