static void bswap_h(unsigned char Hb[16], const unsigned char H[16]) {
    for (int i = 0; i < 8; i++) {
        Hb[i] = H[7 - i];
        Hb[8 + i] = H[15 - i];
    }
}

static PyObject *py_encrypt(PyObject *self, PyObject *args) {
    Py_buffer key_buf, nonce_buf, pt_buf, aad_buf;
    memset(&aad_buf, 0, sizeof(aad_buf));
    if (!PyArg_ParseTuple(args, "y*y*y*|y*", &key_buf, &nonce_buf, &pt_buf, &aad_buf))
        return NULL;

    int keylen = (int)key_buf.len;
    if ((keylen != 16 && keylen != 24 && keylen != 32) || nonce_buf.len != 12) {
        PyErr_SetString(PyExc_ValueError, "unsupported key/nonce size");
        goto fail;
    }

    AES_KEY aeskey;
    if (aesni_set_encrypt_key((const unsigned char *)key_buf.buf, keylen * 8, &aeskey) != 0) {
        PyErr_SetString(PyExc_RuntimeError, "set_key failed");
        goto fail;
    }

    unsigned char H[16], Hb[16], zero[16] = {0};
    aesni_encrypt(zero, H, &aeskey);
    bswap_h(Hb, H);
    unsigned char htable[512];
    memset(htable, 0, sizeof(htable));
    gcm_init_avx(htable, Hb);

    Py_ssize_t ptlen = pt_buf.len;
    /* Allocate ciphertext+16 and later resize down? We need separate tag object.
       Allocate exactly ptlen; tag is 16 separate bytes (tiny). */
    PyObject *ct_obj = PyBytes_FromStringAndSize(NULL, ptlen);
    PyObject *tag_obj = PyBytes_FromStringAndSize(NULL, 16);
    if (!ct_obj || !tag_obj) {
        Py_XDECREF(ct_obj);
        Py_XDECREF(tag_obj);
        goto fail;
    }
    unsigned char *ct = (unsigned char *)PyBytes_AS_STRING(ct_obj);
    unsigned char *tag = (unsigned char *)PyBytes_AS_STRING(tag_obj);
    const unsigned char *pt = (const unsigned char *)pt_buf.buf;
    const unsigned char *nonce = (const unsigned char *)nonce_buf.buf;
    const unsigned char *aad = aad_buf.buf ? (const unsigned char *)aad_buf.buf : NULL;
    Py_ssize_t aadlen = aad_buf.buf ? aad_buf.len : 0;

    size_t nblocks = (size_t)ptlen / 16;
    size_t tail = (size_t)ptlen % 16;

    unsigned char ivec[16];
    memcpy(ivec, nonce, 12);
    ivec[12] = 0; ivec[13] = 0; ivec[14] = 0; ivec[15] = 2;
    if (nblocks)
        aesni_ctr32_encrypt_blocks(pt, ct, nblocks, &aeskey, ivec);
    if (tail) {
        unsigned char ks[16], iv2[16];
        memcpy(iv2, nonce, 12);
        uint32_t ctr = 2u + (uint32_t)nblocks;
        iv2[12] = (unsigned char)(ctr >> 24);
        iv2[13] = (unsigned char)(ctr >> 16);
        iv2[14] = (unsigned char)(ctr >> 8);
        iv2[15] = (unsigned char)ctr;
        aesni_encrypt(iv2, ks, &aeskey);
        for (size_t i = 0; i < tail; i++)
            ct[nblocks * 16 + i] = pt[nblocks * 16 + i] ^ ks[i];
    }

    unsigned char Xi[16];
    memset(Xi, 0, 16);
    if (aadlen) {
        size_t full = (size_t)aadlen & ~(size_t)15;
        if (full)
            gcm_ghash_avx(Xi, htable, aad, full);
        size_t at = (size_t)aadlen & 15;
        if (at) {
            unsigned char block[16];
            memset(block, 0, 16);
            memcpy(block, aad + full, at);
            gcm_ghash_avx(Xi, htable, block, 16);
        }
    }
    if (nblocks)
        gcm_ghash_avx(Xi, htable, ct, nblocks * 16);
    if (tail) {
        unsigned char block[16];
        memset(block, 0, 16);
        memcpy(block, ct + nblocks * 16, tail);
        gcm_ghash_avx(Xi, htable, block, 16);
    }
    unsigned char lb[16];
    memset(lb, 0, 16);
    uint64_t aad_bits = (uint64_t)aadlen * 8;
    uint64_t ct_bits = (uint64_t)ptlen * 8;
    for (int i = 0; i < 8; i++) {
        lb[i] = (unsigned char)(aad_bits >> (56 - 8 * i));
        lb[8 + i] = (unsigned char)(ct_bits >> (56 - 8 * i));
    }
    gcm_ghash_avx(Xi, htable, lb, 16);

    unsigned char J0[16], j0in[16];
    memcpy(j0in, nonce, 12);
    j0in[12] = 0; j0in[13] = 0; j0in[14] = 0; j0in[15] = 1;
    aesni_encrypt(j0in, J0, &aeskey);
    for (int i = 0; i < 16; i++)
        tag[i] = Xi[i] ^ J0[i];

    PyObject *res = Py_BuildValue("{s:N,s:N}", "ciphertext", ct_obj, "tag", tag_obj);
    PyBuffer_Release(&key_buf);
    PyBuffer_Release(&nonce_buf);
    PyBuffer_Release(&pt_buf);
    if (aad_buf.buf) PyBuffer_Release(&aad_buf);
    return res;

fail:
    PyBuffer_Release(&key_buf);
    PyBuffer_Release(&nonce_buf);
    PyBuffer_Release(&pt_buf);
    if (aad_buf.buf) PyBuffer_Release(&aad_buf);
    return NULL;
}

static PyMethodDef methods[] = {
    {"encrypt", py_encrypt, METH_VARARGS, NULL},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "aesgcm_fast", NULL, -1, methods
};
