    /* H^2 via ghash of 16 zero bytes starting from Xi=H? 
       ghash(Xi, block) = (Xi XOR block) * H.
       So ghash(0, H) = H * H = H^2. Yes! block = H (raw), Xi starts 0. */
    unsigned char Xi[16]; memset(Xi,0,16);
    gcm_ghash_avx(Xi, htable, H, 16);
    printf("ghash(H) "); for(int i=0;i<16;i++) printf("%02x", Xi[i]);
    printf("  match %d\n", memcmp(Xi, H2, 16)==0);

    /* What if we pass Hb? */
    memset(Xi,0,16);
    gcm_ghash_avx(Xi, htable, Hb, 16);
    printf("ghash(Hb) "); for(int i=0;i<16;i++) printf("%02x", Xi[i]); printf("\n");

    /* So to compute X * H^k: start Xi = X, ghash k zero blocks.
       To compute H^k itself: start Xi = 0, ghash the block that is H, then (k-1) zero blocks?
       ghash(0, H || 0^{k-1}) = H * H^k = H^{k+1}? Let's check.
       ghash one block H = H^2. ghash two blocks H||0 = H^2 * H = H^3. Yes.
       So H^{k} = ghash(0, H || 0^{k-2}) for k>=2, length (k-1)*16. */

    /* Verify H^3 */
    unsigned char H3[16]; mul_reflected(H3, H2, H);
    unsigned char buf[32]; memcpy(buf, H, 16); memset(buf+16, 0, 16);
    memset(Xi,0,16);
    gcm_ghash_avx(Xi, htable, buf, 32);
    printf("H^3 match %d\n", memcmp(Xi, H3, 16)==0);

    /* Now the reduction identity:
       partial[i] = GHASH(chunk_i) = C_i * H^{len_i}
       total = p0*H^{L1+L2+L3} + p1*H^{L2+L3} + p2*H^{L3} + p3
       Check on 2 chunks of known data. */
    unsigned char data[64];
    for(int i=0;i<64;i++) data[i]=i+1;
    unsigned char all[16]; memset(all,0,16);
    gcm_ghash_avx(all, htable, data, 64);

    unsigned char p0[16], p1[16];
    memset(p0,0,16); gcm_ghash_avx(p0, htable, data, 32);       /* 2 blocks */
    memset(p1,0,16); gcm_ghash_avx(p1, htable, data+32, 32);
    /* total should be p0 * H^2 + p1 */
    unsigned char p0_h2[16]; mul_reflected(p0_h2, p0, H2);
    for(int i=0;i<16;i++) p0_h2[i]^=p1[i];
    printf("2-chunk reduction match %d\n", memcmp(p0_h2, all, 16)==0);

    /* 4 chunks of 1 block */
    unsigned char ps[4][16];
    for(int c=0;c<4;c++){ memset(ps[c],0,16); gcm_ghash_avx(ps[c], htable, data+16*c, 16); }
    /* acc = ps[3]
       acc = ps[2]*H^1 + acc? len of chunk 3 is 1, so acc = ps[2]*H^{1} XOR ps[3]
       then acc = ps[1]*H^{2} XOR acc
       then acc = ps[0]*H^{3} XOR acc */
    unsigned char acc[16]; memcpy(acc, ps[3], 16);
    unsigned char powers[4][16];
    memcpy(powers[1], H, 16);          /* H^1 */
    memcpy(powers[2], H2, 16);
    memcpy(powers[3], H3, 16);
    unsigned char tmp[16];
    mul_reflected(tmp, ps[2], powers[1]); for(int i=0;i<16;i++) acc[i]^=tmp[i];
    mul_reflected(tmp, ps[1], powers[2]); for(int i=0;i<16;i++) acc[i]^=tmp[i];
    mul_reflected(tmp, ps[0], powers[3]); for(int i=0;i<16;i++) acc[i]^=tmp[i];
    printf("4-chunk reduction match %d\n", memcmp(acc, all, 16)==0);
    return 0;
}
