static Chunk jobs[NTH];
static pthread_t threads[NTH];
static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv_go = PTHREAD_COND_INITIALIZER;
static pthread_cond_t cv_done = PTHREAD_COND_INITIALIZER;
static int epoch = 0;
static int remaining = 0;
static int stop_flag = 0;
static int pool_ready = 0;

static void *worker(void *arg) {
    int id = (int)(long)arg;
    int seen = 0;
    for (;;) {
        pthread_mutex_lock(&mu);
        while (epoch == seen && !stop_flag)
            pthread_cond_wait(&cv_go, &mu);
        if (stop_flag) { pthread_mutex_unlock(&mu); break; }
        seen = epoch;
        pthread_mutex_unlock(&mu);

        Chunk *c = &jobs[id];
        if (c->nblocks) {
            unsigned char ivec[16];
