}

static void pool_init(void) {
    if (pool_ready) return;
    for (int i = 0; i < NTH; i++)
        pthread_create(&threads[i], NULL, worker, (void *)(long)i);
    pool_ready = 1;
}

static void pool_dispatch(void) {
    pthread_mutex_lock(&mu);
    remaining = NTH;
    epoch++;
    pthread_cond_broadcast(&cv_go);
    while (remaining > 0) pthread_cond_wait(&cv_done, &mu);
    pthread_mutex_unlock(&mu);
}

/* H^{nblocks} via repeated squaring. pows[i] = H^{2^i}. */
static void ghash_pow(unsigned char out[16], const unsigned char H[16], size_t exp) {
    unsigned char base[16], acc[16];
    memcpy(base, H, 16);
