static void ghash_mul(unsigned char z[16], const unsigned char x[16], const unsigned char h[16]) {
    unsigned char V[16], Z[16];
    memcpy(V, h, 16);
    memset(Z, 0, 16);
    for (int i = 0; i < 128; i++) {
