        int lsb = V[15] & 1;
        for (int k = 15; k > 0; k--)
            V[k] = (unsigned char)((V[k] >> 1) | (V[k - 1] << 7));
        V[0] >>= 1;
        if (lsb) V[0] ^= 0xe1;
    }
    memcpy(z, Z, 16);
}

static void ghash_pow(unsigned char out[16], const unsigned char H[16], size_t exp) {
    unsigned char base[16], acc[16] = {0x80, 0};
    memcpy(base, H, 16);
    while (exp) {
        if (exp & 1) {
            unsigned char t[16];
            ghash_mul(t, acc, base);
            memcpy(acc, t, 16);
        }
        exp >>= 1;
        if (exp) {
            unsigned char t[16];
            ghash_mul(t, base, base);
            memcpy(base, t, 16);
        }
    }
    memcpy(out, acc, 16);
}

typedef struct {
    const unsigned char *pt;
    unsigned char *ct;
    const AES_KEY *aeskey;
    const unsigned char *htable;
    unsigned char nonce[12];
    size_t start_block;
    size_t nblocks;
    unsigned char partial[16];
} Chunk;

static Chunk jobs[NTH];
static pthread_t threads[NTH];
static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv_go = PTHREAD_COND_INITIALIZER;
static pthread_cond_t cv_done = PTHREAD_COND_INITIALIZER;
static int epoch = 0, remaining = 0, stop_flag = 0, pool_ready = 0;

static void *worker(void *arg) {
    int id = (int)(long)arg;
    int seen = 0;
    for (;;) {
        pthread_mutex_lock(&mu);
        while (epoch == seen && !stop_flag)
            pthread_cond_wait(&cv_go, &mu);
        if (stop_flag) { pthread_mutex_unlock(&mu); break; }
        seen = epoch;
        pthread_mutex_unlock(&mu);

        Chunk *c = &jobs[id];
        if (c->nblocks) {
            unsigned char ivec[16];
            memcpy(ivec, c->nonce, 12);
            uint32_t ctr = 2u + (uint32_t)c->start_block;
            ivec[12] = (unsigned char)(ctr >> 24);
            ivec[13] = (unsigned char)(ctr >> 16);
            ivec[14] = (unsigned char)(ctr >> 8);
            ivec[15] = (unsigned char)ctr;
            aesni_ctr32_encrypt_blocks(c->pt + c->start_block * 16,
                                       c->ct + c->start_block * 16,
                                       c->nblocks, c->aeskey, ivec);
            memset(c->partial, 0, 16);
            gcm_ghash_avx(c->partial, c->htable, c->ct + c->start_block * 16, c->nblocks * 16);
        } else {
            memset(c->partial, 0, 16);
        }
        pthread_mutex_lock(&mu);
        remaining--;
        if (remaining == 0) pthread_cond_signal(&cv_done);
        pthread_mutex_unlock(&mu);
    }
    return NULL;
}

static void pool_init(void) {
    if (pool_ready) return;
    for (int i = 0; i < NTH; i++)
        pthread_create(&threads[i], NULL, worker, (void *)(long)i);
    pool_ready = 1;
}

static PyObject *py_encrypt(PyObject *self, PyObject *args) {
    Py_buffer key_buf, nonce_buf, pt_buf, aad_buf;
    memset(&aad_buf, 0, sizeof(aad_buf));
    if (!PyArg_ParseTuple(args, "y*y*y*|y*", &key_buf, &nonce_buf, &pt_buf, &aad_buf))
        return NULL;

    int keylen = (int)key_buf.len;
    if ((keylen != 16 && keylen != 24 && keylen != 32) || nonce_buf.len != 12) {
        PyErr_SetString(PyExc_ValueError, "unsupported key/nonce size");
        goto fail;
    }

    AES_KEY aeskey;
    if (aesni_set_encrypt_key((const unsigned char *)key_buf.buf, keylen * 8, &aeskey) != 0) {
        PyErr_SetString(PyExc_RuntimeError, "set_key failed");
        goto fail;
    }

    unsigned char H[16], Hb[16], zero[16] = {0};
    aesni_encrypt(zero, H, &aeskey);
    for (int i = 0; i < 8; i++) { Hb[i] = H[7 - i]; Hb[8 + i] = H[15 - i]; }
    unsigned char htable[512];
    memset(htable, 0, sizeof(htable));
    gcm_init_avx(htable, Hb);

    Py_ssize_t ptlen = pt_buf.len;
    PyObject *ct_obj = PyBytes_FromStringAndSize(NULL, ptlen);
    PyObject *tag_obj = PyBytes_FromStringAndSize(NULL, 16);
    if (!ct_obj || !tag_obj) { Py_XDECREF(ct_obj); Py_XDECREF(tag_obj); goto fail; }

    unsigned char *ct = (unsigned char *)PyBytes_AS_STRING(ct_obj);
    unsigned char *tag = (unsigned char *)PyBytes_AS_STRING(tag_obj);
    const unsigned char *pt = (const unsigned char *)pt_buf.buf;
    const unsigned char *nonce = (const unsigned char *)nonce_buf.buf;
    const unsigned char *aad = aad_buf.buf ? (const unsigned char *)aad_buf.buf : NULL;
    Py_ssize_t aadlen = aad_buf.buf ? aad_buf.len : 0;

    size_t nblocks = (size_t)ptlen / 16;
    size_t tail = (size_t)ptlen % 16;
    unsigned char Xi[16] = {0};

    if (nblocks >= 1024) {
        pool_init();
        size_t base = nblocks / NTH;
        size_t rem = nblocks % NTH;
        size_t off = 0;
        size_t lens[NTH];
        for (int i = 0; i < NTH; i++) {
            size_t nb = base + ((size_t)i < rem ? 1 : 0);
            lens[i] = nb;
            jobs[i].pt = pt;
            jobs[i].ct = ct;
            jobs[i].aeskey = &aeskey;
            jobs[i].htable = htable;
            memcpy(jobs[i].nonce, nonce, 12);
            jobs[i].start_block = off;
            jobs[i].nblocks = nb;
            off += nb;
        }
        pthread_mutex_lock(&mu);
        remaining = NTH;
        epoch++;
        pthread_cond_broadcast(&cv_go);
        while (remaining > 0) pthread_cond_wait(&cv_done, &mu);
        pthread_mutex_unlock(&mu);

        unsigned char later[16] = {0x80, 0};
        unsigned char acc[16] = {0};
        for (int i = NTH - 1; i >= 0; i--) {
            unsigned char term[16];
            ghash_mul(term, jobs[i].partial, later);
            for (int k = 0; k < 16; k++) acc[k] ^= term[k];
            if (i > 0 && lens[i]) {
                unsigned char pw[16], t[16];
                ghash_pow(pw, H, lens[i]);
                ghash_mul(t, later, pw);
                memcpy(later, t, 16);
            }
        }
        memcpy(Xi, acc, 16);
    } else {
        unsigned char ivec[16];
        memcpy(ivec, nonce, 12);
        ivec[12] = 0; ivec[13] = 0; ivec[14] = 0; ivec[15] = 2;
        if (nblocks)
            aesni_ctr32_encrypt_blocks(pt, ct, nblocks, &aeskey, ivec);
        if (nblocks)
            gcm_ghash_avx(Xi, htable, ct, nblocks * 16);
    }

    if (tail) {
        unsigned char ks[16], iv2[16];
        memcpy(iv2, nonce, 12);
        uint32_t ctr = 2u + (uint32_t)nblocks;
        iv2[12] = (unsigned char)(ctr >> 24);
        iv2[13] = (unsigned char)(ctr >> 16);
        iv2[14] = (unsigned char)(ctr >> 8);
        iv2[15] = (unsigned char)ctr;
        aesni_encrypt(iv2, ks, &aeskey);
        for (size_t i = 0; i < tail; i++)
            ct[nblocks * 16 + i] = pt[nblocks * 16 + i] ^ ks[i];
        unsigned char block[16] = {0};
        memcpy(block, ct + nblocks * 16, tail);
        gcm_ghash_avx(Xi, htable, block, 16);
    }

    if (aadlen) {
        unsigned char Xi_ct[16];
        memcpy(Xi_ct, Xi, 16);
        unsigned char Xi_aad[16] = {0};
        size_t full = (size_t)aadlen & ~(size_t)15;
        if (full) gcm_ghash_avx(Xi_aad, htable, aad, full);
        if ((size_t)aadlen & 15) {
            unsigned char block[16] = {0};
            memcpy(block, aad + full, (size_t)aadlen & 15);
            gcm_ghash_avx(Xi_aad, htable, block, 16);
        }
        unsigned char pw[16], term[16];
        ghash_pow(pw, H, nblocks + (tail ? 1 : 0));
        ghash_mul(term, Xi_aad, pw);
        for (int k = 0; k < 16; k++) Xi[k] = term[k] ^ Xi_ct[k];
    }

    unsigned char lb[16] = {0};
    uint64_t aad_bits = (uint64_t)aadlen * 8;
    uint64_t ct_bits = (uint64_t)ptlen * 8;
    for (int i = 0; i < 8; i++) {
        lb[i] = (unsigned char)(aad_bits >> (56 - 8 * i));
        lb[8 + i] = (unsigned char)(ct_bits >> (56 - 8 * i));
    }
    gcm_ghash_avx(Xi, htable, lb, 16);

    unsigned char J0[16], j0in[16];
    memcpy(j0in, nonce, 12);
    j0in[12] = 0; j0in[13] = 0; j0in[14] = 0; j0in[15] = 1;
    aesni_encrypt(j0in, J0, &aeskey);
    for (int i = 0; i < 16; i++) tag[i] = Xi[i] ^ J0[i];

    PyObject *res = Py_BuildValue("{s:N,s:N}", "ciphertext", ct_obj, "tag", tag_obj);
    PyBuffer_Release(&key_buf);
    PyBuffer_Release(&nonce_buf);
    PyBuffer_Release(&pt_buf);
    if (aad_buf.buf) PyBuffer_Release(&aad_buf);
    return res;

fail:
    PyBuffer_Release(&key_buf);
    PyBuffer_Release(&nonce_buf);
    PyBuffer_Release(&pt_buf);
    if (aad_buf.buf) PyBuffer_Release(&aad_buf);
    return NULL;
}

static PyMethodDef methods[] = {
    {"encrypt", py_encrypt, METH_VARARGS, NULL},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "aesgcm_fast", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_aesgcm_fast(void) { return PyModule_Create(&moduledef); }
EOF
